def parsePort(text: String): Either[String, Int] =
  text.trim.toIntOption match {
    case Some(p) if p >= 1 && p <= 65535 => Right(p)
    case Some(p)                         => Left(s"out of range: $p")
    case None                            => Left(s"not a number: $text")
  }

parsePort(raw) match {
  case Right(port) => println(s"port $port")
  case Left(why)   => println(s"invalid: $why")
}

val doubled = for (port <- parsePort(raw)) yield port * 2   // a Left short-circuits
